refentry.refsect1:
&reftitle.description;
public intReflectionAttribute::getTarget
Devuelve el tipo de declaración al que se aplica este atributo. Esto es distinto del conjunto de objetivos permitidos por la clase del atributo.

  &reftitle.examples;

   Distinción entre los objetivos reales y los permitidos de un atributo


<?php
#[Attribute(Attribute::TARGET_CLASS | Attribute::TARGET_PROPERTY)]
class Marker {}

#[Marker]
class Example
{
    #[Marker]
    public $value;
}

$class = new ReflectionClass(Example::class);
$property = new ReflectionProperty(Example::class, 'value');

var_dump($class->getAttributes(Marker::class)[0]->getTarget());
var_dump($property->getAttributes(Marker::class)[0]->getTarget());

$definition = new ReflectionClass(Marker::class);
var_dump($definition->getAttributes(Attribute::class)[0]->newInstance()->flags);
?>


   &example.outputs;


int(1)
int(8)
int(9)
